<?php
declare(strict_types=1);require_once __DIR__.'/includes/ui.php';require_once __DIR__.'/includes/digivolution.php';pv_require_login();$db=pv_db();$uid=(int)$_SESSION['myid'];$error='';$notice=(string)($_SESSION['dn_evolution_notice']??'');unset($_SESSION['dn_evolution_notice']);
$id=(int)($_POST['digimon_id']??$_GET['id']??0);
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{
    pv_require_csrf();
    if(($_POST['action']??'evolve')==='train'){dn_train_stat($db,$uid,$id,(string)($_POST['stat']??''),(int)($_POST['delta']??0));$notice='Training allocation updated.';}
    else {$r=dn_digivolve($db,$uid,$id,(string)($_POST['target']??''),(string)($_POST['direction']??''),(int)($_POST['partner_id']??0));$notice=$r['from'].' became '.$r['to'].' · Level '.$r['level'].' · +'.$r['gain'].' ABI ('.$r['abi'].' total).';}
    $_SESSION['dn_evolution_notice']=$notice;pv_redirect('digivolution.php?id='.$id);
}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Evolution could not be completed. No changes were committed.';pv_log('Evolution: '.$e->getMessage());}
$collection=dn_collection_rows($db,$uid);$d=null;foreach($collection as $row)if((int)$row['id']===$id)$d=$row;if(!$d&&$collection){$d=$collection[0];$id=(int)$d['id'];}
$options=$d?dn_digivolution_options($d['slug']):[];$active=dn_active_battle($db,$uid);$busy=$active&&empty($active['finished']);pv_page_start('Digivolution & ABI','digivolution.php',true);
?>
<div class="pv-game-layout"><?php pv_game_side_menu('digivolution.php');?><main class="pv-main-column"><section class="pv-page"><div class="pv-page-head"><?php nxt_page_sprites();?><div><span class="pv-eyebrow">DIGILAB // EVOLUTION & TRAINING</span><h1>Digivolution & ABI</h1><p class="pv-subtle">Digivolve or de-digivolve to build ABI. Both reset level and EXP, restore vitals, and retain learned inherited moves. Signature moves belong to the current form. ABI is capped at 200. Free mode changes preserve level, EXP and ABI.</p></div></div>
<?php if($notice):?><div class="pv-flash success" role="status"><?=pv_h($notice)?></div><?php endif;?><?php if($error):?><div class="pv-flash error" role="alert"><?=pv_h($error)?></div><?php endif;?>
<?php if($d):?>
<form method="get" class="dn-lab-selector"><label>Choose Digimon<select name="id"><?php foreach($collection as $row):?><option value="<?=(int)$row['id']?>" <?=(int)$row['id']===$id?'selected':''?>><?=pv_h($row['nickname']?:$row['name'])?> · #<?=(int)$row['id']?> · Lv. <?=(int)$row['level']?> · ABI <?=(int)$row['abi']?></option><?php endforeach;?></select></label><button class="pv-button pv-button-secondary">View routes</button></form>
<?=dn_digimon_card($d)?>
<p class="pv-subtle">ABI <?=(int)$d['abi']?> / 200 · CAM <?=(int)$d['cam']?>% · ATK <?=(int)$d['attack_stat']?> · DEF <?=(int)$d['defense_stat']?> · INT <?=(int)$d['intelligence_stat']?> · SPD <?=(int)$d['speed_stat']?></p>
<?php if($busy):?><div class="pv-flash">Finish your <a href="<?=pv_h(pv_url('wildbattle.php'))?>">active wild battle</a> before changing forms or training.</div><?php endif;?>
<div class="dn-evolution-options"><?php foreach($options as $rule):$to=dn_species_by_slug($db,$rule['target']);if(!$to)continue;$requirements=dn_evolution_requirements($db,$uid,$d,$rule);$ready=!$busy;foreach($requirements as $r)$ready=$ready&&$r['ready'];$partners=[];if(!empty($rule['partner'])){foreach($collection as $row)if($row['slug']===$rule['partner']&&(int)$row['cam']>=100&&!(int)$row['locked_trade']&&(int)$row['hp']>0&&(int)$row['id']!==$id)$partners[]=$row;$ready=$ready&&count($partners)>0;}$gain=!empty($rule['mode_change'])?0:min(200-(int)$d['abi'],dn_abi_gain($d['stage'],$to['stage'],(int)$d['level'],$rule['direction']));?>
<article class="dn-route"><small><?=strtoupper($rule['direction']==='mode'?'Mode Change':($rule['direction']==='down'?'De-digivolution':(!empty($rule['partner'])?'DNA Digivolution':'Digivolution')))?></small><div><img loading="lazy" src="<?=pv_h(pv_static($to['sprite']))?>" alt="<?=pv_h($to['name'])?>"></div><h3><?=pv_h($to['name'])?></h3><p class="pv-subtle"><?=pv_h($to['stage'])?> · Level <?=!empty($rule['mode_change'])?(int)$d['level']:1?> · +<?=$gain?> ABI</p>
<?php if(str_contains($rule['origin']??'','NXT extension')):?><p class="pv-subtle">NXT evolution branch</p><?php endif;?>
<div class="dn-requirements"><?php foreach($requirements as $r):?><span class="<?=$r['ready']?'ready':''?>"><?=pv_h($r['label'])?> <?=$r['value']?> / <?=$r['need']?></span><?php endforeach;?></div>
<form method="post"><?=pv_csrf_field()?><input type="hidden" name="digimon_id" value="<?=$id?>"><input type="hidden" name="target" value="<?=pv_h($rule['target'])?>"><input type="hidden" name="direction" value="<?=pv_h($rule['direction'])?>">
<?php if(!empty($rule['partner'])):?><p class="pv-subtle">Fusion consumes the selected <?=pv_h(dn_species_meta($rule['partner'])['name']??$rule['partner'])?> and inherits its learned moves. Both partners need 100 CAM.</p><label>Fusion partner<select name="partner_id"><?php foreach($partners as $partner):?><option value="<?=(int)$partner['id']?>"><?=pv_h($partner['nickname']?:$partner['name'])?> #<?=(int)$partner['id']?> · Lv. <?=(int)$partner['level']?> · consumed</option><?php endforeach;?></select></label><?php endif;?>
<button class="pv-button" <?=$ready?'':'disabled'?>><?=!empty($rule['partner'])?'Fuse · consume partner':($rule['direction']==='mode'?'Change mode':($rule['direction']==='down'?'De-digivolve':'Digivolve'))?></button></form></article><?php endforeach;?></div>
<?php if(!$options):?><div class="pv-empty">No compatible evolution route is currently available for this form.</div><?php endif;?>
<section class="dn-training"><h2>ABI training</h2><?php $training=dn_training($d);$budget=50+intdiv((int)$d['abi'],2);?><p class="pv-subtle">Allocate bonus stats to meet evolution requirements. <?=array_sum($training)?> / <?=$budget?> points used. One HP point gives 10 HP; other points give 1 stat. Removing points makes them available again.</p><p><?php foreach(['hp','sp','atk','def','int','spd'] as $st):?><?=strtoupper($st)?> +<?=(int)($training[$st]??0)*($st==='hp'?10:1)?> &nbsp; <?php endforeach;?></p>
<form method="post"><?=pv_csrf_field()?><input type="hidden" name="action" value="train"><input type="hidden" name="digimon_id" value="<?=$id?>"><label>Stat<select name="stat"><?php foreach(['hp','sp','atk','def','int','spd'] as $st):?><option value="<?=$st?>"><?=strtoupper($st)?></option><?php endforeach;?></select></label><label>Adjustment<select name="delta"><option value="1">+1 point</option><option value="5">+5 points</option><option value="-1">−1 point</option><option value="-5">−5 points</option></select></label><button class="pv-button pv-button-secondary" <?=$busy||(int)$d['locked_trade']?'disabled':''?>>Apply training</button></form></section>
<section class="dn-training"><h2>Known moves</h2><ul class="dn-move-list"><?php foreach(dn_instance_moves($db,$d) as $move):?><li><strong><?=pv_h($move['name'])?></strong> · <?=(int)$move['sp']?> SP · <?=pv_h(dn_move_summary($move))?> · <?=$move['inheritable']?'Inherited':'Current signature'?></li><?php endforeach;?></ul></section>
<?php else:?><div class="pv-empty">Materialize a Digimon to begin training.</div><?php endif;?></section></main></div><?php pv_page_end();?>
